(284463, 19893, 7528, '<td valign="top">I think the color swap is harsh...  composition needs improvement..  or perhaps a better crop</td>', 'I think the color swap is harsh...  composition needs improvement..  or perhaps a better crop', '2003-05-01 03:27:39.000000', NULL, 1),
(284465, 19966, 6019, '<td valign="top">nicely composed, well done!</td>', 'nicely composed, well done!', '2003-05-01 03:33:49.000000', NULL, 1),
