(284469, 19730, 7528, '<td valign="top">good metaphor ..  i like the soft colors / fog combo but I don''t know, that dryad-ish looking  tree is almost too centered.... but then the road on the side works....</td>', 'good metaphor ..  i like the soft colors / fog combo but I don''t know, that dryad-ish looking  tree is almost too centered.... but then the road on the side works....', '2003-05-01 03:35:18.000000', NULL, 1),
(284480, 19786, 7885, '<td valign="top">The grainy finish is a nice touch.</td>', 'The grainy finish is a nice touch.', '2003-05-01 04:12:45.000000', NULL, 1),
(284481, 19498, 6359, '<td valign="top">sorry I had to deduct for upside down horse.  it is still a 9</td>', 'sorry I had to deduct for upside down horse.  it is still a 9', '2003-05-01 04:21:37.000000', NULL, 1),
(284482, 20008, 7885, '<td valign="top">Spookiest ghost-related shot in the challenge.</td>', 'Spookiest ghost-related shot in the challenge.', '2003-05-01 04:24:58.000000', NULL, 1),
