(287283, 20005, 6325, '<td valign="top">Cool mechanism. Colors are very good.</td>', 'Cool mechanism. Colors are very good.', '2003-05-04 21:30:32.000000', NULL, 1),
(287284, 19969, 3306, '<td valign="top">I really like your picture. It is purposeful and interesting. The bird in the upper left adds interest. I wish the orange wasn''t so bright on the fishermans raingear. If it wasn''t for that this would be a 10. Still very good and one of my favorites.</td>', 'I really like your picture. It is purposeful and interesting. The bird in the upper left adds interest. I wish the orange wasn''t so bright on the fishermans raingear. If it wasn''t for that this would be a 10. Still very good and one of my favorites.', '2003-05-04 21:30:44.000000', NULL, 1),
(287285, 19642, 7510, '<td valign="top">OK  I don''t get the title, but it''s a nice Photo.  Nice Texture.  Maybe if the wing tip wasn''t cropped off...</td>', 'OK  I don''t get the title, but it''s a nice Photo.  Nice Texture.  Maybe if the wing tip wasn''t cropped off...', '2003-05-04 21:31:29.000000', NULL, 1),
(287286, 19949, 7510, '<td valign="top">Too far away.  the extra stuff in the forground distracts.  Otherwise a nice photo.</td>', 'Too far away.  the extra stuff in the forground distracts.  Otherwise a nice photo.', '2003-05-04 21:32:55.000000', NULL, 1),
(287289, 19824, 7510, '<td valign="top">What''s with the black along the bottom.  Looks like a shot from an apollo mission.  It gives an intriguing feel. (8)</td>', 'What''s with the black along the bottom.  Looks like a shot from an apollo mission.  It gives an intriguing feel. (8)', '2003-05-04 21:39:00.000000', NULL, 1),
(287290, 19306, 7510, '<td valign="top">What''s with the flare down the center.  I don''t feel that it adds anything to the photo.</td>', 'What''s with the flare down the center.  I don''t feel that it adds anything to the photo.', '2003-05-04 21:41:06.000000', NULL, 1),
